package com.d104.pnt.ui.game.playimport androidx.lifecycle.SavedStateHandleimport androidx.lifecycle.ViewModelimport androidx.lifecycle.viewModelScopeimport com.d104.pnt.data.repository.AuthRepositoryimport com.d104.pnt.data.repository.GameSessionEventimport com.d104.pnt.data.repository.GameSessionRepositoryimport com.d104.pnt.domain.model.GameRoleimport com.d104.pnt.navigation.NavArgsimport com.d104.pnt.util.socket.GameSocketManagerimport dagger.hilt.android.lifecycle.HiltViewModelimport kotlinx.coroutines.delayimport kotlinx.coroutines.flow.MutableStateFlowimport kotlinx.coroutines.flow.asStateFlowimport kotlinx.coroutines.flow.firstimport kotlinx.coroutines.launchimport kotlinx.coroutines.withTimeoutOrNullimport timber.log.Timberimport javax.inject.Inject@HiltViewModelclass GameRoleViewModel @Inject constructor(    private val authRepository: AuthRepository,    private val gameSocketManager: GameSocketManager,    private val savedStateHandle: SavedStateHandle,    private val gameSessionRepository: GameSessionRepository) : ViewModel() {    private val roomId: Long = savedStateHandle.get<Long>(NavArgs.ROOM_ID) ?: 0L    private val roleName: String = savedStateHandle.get<String>(NavArgs.ROLE) ?: "THIEF"    val role: GameRole = GameRole.fromName(roleName)    private val _flowStatus = MutableStateFlow<GameFlowStatus>(GameFlowStatus.RoleReveal(role))    val flowStatus = _flowStatus.asStateFlow()    private val _connectionStatus = MutableStateFlow<ConnectionStatus>(ConnectionStatus.Connecting)    val connectionStatus = _connectionStatus.asStateFlow()    init {        gameSessionRepository.connectAndJoin(roomId)        Timber.d("RoomId: $roomId")        observeRepositoryEvents()    }    private fun observeRepositoryEvents() {        viewModelScope.launch {            gameSessionRepository.eventFlow.collect { event ->                when (event) {                    is GameSessionEvent.GameStarted -> {                        Timber.d("🚀 레포지토리에서 게임 시작 신호 수신!")                        _flowStatus.value = GameFlowStatus.CountDown(event.gameId)                    }                    is GameSessionEvent.GameEnded -> {                        Timber.d("레포지토리에서 게임 종료 신호 수신!")                    }                    is GameSessionEvent.ErrorOccurred -> {                        Timber.e("레포지토리에서 에러 발생: ${event.message}")                    }                    is GameSessionEvent.NavigateToNews -> {}                    else -> {}                }            }        }    }    private fun setupListeners() {        // Join 성공 확인 (로그용)        gameSocketManager.setOnJoinedRoom { gameId, memberId, message ->        }        // get will start game        gameSocketManager.setOnWillStartGame { gameId, willStartAt ->            Timber.d("⏰ 5초 후 게임 시작 - gameId: $gameId, willStartAt: $willStartAt")            _connectionStatus.value = ConnectionStatus.WillStart(willStartAt)        }        // get start game - 도둑 도망 화면으로 이동        gameSocketManager.setOnGameStarted { gameId, startTime ->            Timber.d("🏁 게임 시작! - gameId: $gameId, startTime: $startTime")            _flowStatus.value = GameFlowStatus.CountDown(gameId)        }        gameSocketManager.setOnJoinedRoom { gameId, memberId, message ->            Timber.d("✅ 게임 입장 성공: gameId=$gameId")            _connectionStatus.value = ConnectionStatus.Joined            // Join 직후 현재 게임 상태가 이미 시작되었을 수 있으므로 싱크 요청            gameSocketManager.syncGameInfo()        }        gameSocketManager.setOnGameInfoSynced { data ->            val status = data.optString("status") // 예: "START", "RUNNING" 등 서버 정의 값            Timber.d("📊 게임 정보 싱크 수신: status=$status")            // 만약 이미 게임이 시작된 상태라면 (내가 start 이벤트를 놓쳤다면)            if (status == "STARTED" || status == "START") {                val gameIdFromSync = data.optLong("gameId")                _flowStatus.value = GameFlowStatus.CountDown(gameIdFromSync)            }        }        // 소켓 자체의 재연결 이벤트 감지        gameSocketManager.setOnReconnected {            Timber.d("🔄 소켓 재연결됨 - 다시 Join 시도")            connectAndJoin()        }        gameSocketManager.setOnJoinedRoom { gameId, memberId, message ->            Timber.d("✅ 게임 입장 성공: gameId=$gameId, memberId=$memberId")            _connectionStatus.value = ConnectionStatus.Joined        }    }    private fun connectAndJoin() {        viewModelScope.launch {            try {                val token = authRepository.getAccessToken().first()                if (token.isEmpty()) return@launch                gameSocketManager.connect(token)                // 연결 대기                withTimeoutOrNull(5000) {                    while (!gameSocketManager.isConnected()) {                        delay(200)                    }                }                if (gameSocketManager.isConnected()) {                    _connectionStatus.value = ConnectionStatus.Connected                    gameSocketManager.joinGame(roomId)                    // ⭐ 핵심: Join 후 일정 시간 동안 아무 응답이 없으면(다른 유저 미접속 등)                    // 수동으로 싱크를 다시 찔러서 현재 방 상태를 확인                    delay(2000)                    if (_flowStatus.value is GameFlowStatus.RoleReveal) {                        gameSocketManager.syncGameInfo()                    }                } else {                    _connectionStatus.value = ConnectionStatus.Error("서버와 연결할 수 없습니다.")                }            } catch (e: Exception) {                Timber.e(e, "연결 중 오류")            }        }    }}sealed class GameFlowStatus {    data class RoleReveal(val role: GameRole) : GameFlowStatus()    data class CountDown(val gameId: Long) : GameFlowStatus()}// ⭐ 연결 상태 추가sealed class ConnectionStatus {    object Connecting : ConnectionStatus()    object Connected : ConnectionStatus()    object Joined : ConnectionStatus()    data class WillStart(val willStartAt: String) : ConnectionStatus()    data class Error(val message: String) : ConnectionStatus()}